-- Delivery 6, Part 2 — native Home and Documentation (ADR 020; OPS-26, OPS-27, OPS-28).
-- Documents, their revisions (every save is a new one; the published one is what visitors see) and their images.
-- No content is created here: the one-time Notion import (npm run cms:import-notion) writes the first revisions.
CREATE TABLE "cms_documents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"document_number" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "cms_documents_document_number_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"kind" text NOT NULL,
	"display_order" integer DEFAULT 0 NOT NULL,
	"latest_revision_id" uuid,
	"published_revision_id" uuid,
	"first_published_at" timestamp with time zone,
	"unpublished_at" timestamp with time zone,
	"archived_at" timestamp with time zone,
	"source_ref" text,
	"created_by_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "cms_documents_kind_known" CHECK ("cms_documents"."kind" in ('home', 'article')),
	CONSTRAINT "cms_documents_display_order_range" CHECK ("cms_documents"."display_order" between -100000 and 100000),
	CONSTRAINT "cms_documents_unpublished_not_live" CHECK ("cms_documents"."unpublished_at" is null or "cms_documents"."published_revision_id" is null)
);
--> statement-breakpoint
CREATE TABLE "cms_images" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"storage_key" text NOT NULL,
	"content_type" text NOT NULL,
	"size_bytes" integer NOT NULL,
	"sha256" char(64) NOT NULL,
	"file_name" text NOT NULL,
	"uploaded_by_id" uuid,
	"uploaded_by_label" text NOT NULL,
	"uploaded_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "cms_images_content_type_known" CHECK ("cms_images"."content_type" in ('image/png', 'image/jpeg', 'image/webp', 'image/gif')),
	CONSTRAINT "cms_images_size_range" CHECK ("cms_images"."size_bytes" between 1 and 5242880),
	CONSTRAINT "cms_images_sha256_hex" CHECK ("cms_images"."sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "cms_images_file_name_present" CHECK (char_length(btrim("cms_images"."file_name")) between 1 and 255)
);
--> statement-breakpoint
CREATE TABLE "cms_revisions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"document_id" uuid NOT NULL,
	"number" integer NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"title" text NOT NULL,
	"slug" text NOT NULL,
	"expertise" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"content" jsonb NOT NULL,
	"summary" text,
	"author_id" uuid,
	"author_label" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"published_at" timestamp with time zone,
	"published_by_id" uuid,
	"published_by_label" text,
	"restored_from_id" uuid,
	"content_hash" char(64) NOT NULL,
	CONSTRAINT "cms_revisions_status_known" CHECK ("cms_revisions"."status" in ('draft', 'published')),
	CONSTRAINT "cms_revisions_number_positive" CHECK ("cms_revisions"."number" >= 1),
	CONSTRAINT "cms_revisions_title_length" CHECK (char_length(btrim("cms_revisions"."title")) between 1 and 200),
	CONSTRAINT "cms_revisions_slug_shape" CHECK ("cms_revisions"."slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length("cms_revisions"."slug") <= 100),
	CONSTRAINT "cms_revisions_expertise_array" CHECK (jsonb_typeof("cms_revisions"."expertise") = 'array' and jsonb_array_length("cms_revisions"."expertise") <= 10),
	CONSTRAINT "cms_revisions_content_array" CHECK (jsonb_typeof("cms_revisions"."content") = 'array'),
	CONSTRAINT "cms_revisions_summary_length" CHECK ("cms_revisions"."summary" is null or char_length("cms_revisions"."summary") <= 500),
	CONSTRAINT "cms_revisions_author_label_present" CHECK (char_length(btrim("cms_revisions"."author_label")) between 1 and 120),
	CONSTRAINT "cms_revisions_published_when_published" CHECK (("cms_revisions"."status" = 'published') = ("cms_revisions"."published_at" is not null)),
	CONSTRAINT "cms_revisions_content_hash_hex" CHECK ("cms_revisions"."content_hash" ~ '^[0-9a-f]{64}$')
);
