-- A revision is never rewritten or removed: its words, author and time stay as saved. Only its status moves
-- (draft → published), with who published it and when.
CREATE FUNCTION "cms_revisions_keep_content"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION 'cms_revisions are never deleted (% refused)', TG_OP USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.document_id IS DISTINCT FROM OLD.document_id OR NEW.number IS DISTINCT FROM OLD.number OR NEW.title IS DISTINCT FROM OLD.title
    OR NEW.slug IS DISTINCT FROM OLD.slug OR NEW.expertise IS DISTINCT FROM OLD.expertise OR NEW.content IS DISTINCT FROM OLD.content
    OR NEW.summary IS DISTINCT FROM OLD.summary OR NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.author_label IS DISTINCT FROM OLD.author_label
    OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.restored_from_id IS DISTINCT FROM OLD.restored_from_id OR NEW.content_hash IS DISTINCT FROM OLD.content_hash THEN
    RAISE EXCEPTION 'a cms_revisions row keeps its content: save a new revision instead' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "cms_revisions_keep_content" BEFORE UPDATE OR DELETE ON "cms_revisions" FOR EACH ROW EXECUTE FUNCTION "cms_revisions_keep_content"();--> statement-breakpoint
CREATE TRIGGER "cms_revisions_no_truncate" BEFORE TRUNCATE ON "cms_revisions" FOR EACH STATEMENT EXECUTE FUNCTION "cms_revisions_keep_content"();
